#include <linux/pagemap.h>
#include <linux/mm.h>

int check_pmd_entry(pmd_t *pmd) {
    pmd_t pmd_val;
    int ret = 0;

    pmd_val = *pmd;
    barrier(); /* Ensure atomicity during checks */

    if (pmd_none(pmd_val) || pmd_trans_huge(pmd_val)) {
        ret = 1;
    } else if (pmd_bad(pmd_val)) {
        pmd_clear_bad(pmd);
        ret = 1;
    }

    return ret;
}

int check_pmd_entry(pmd_t *pmd) {
    pmd_t pmd_val = pmd_read_atomic(pmd);
    compiler_barrier();

    if (pmd_none(pmd_val) || pmd_trans_huge(pmd_val) || pmd_bad(pmd_val)) {
        if (pmd_bad(pmd_val)) {
            pmd_clear_bad(pmd);
        }
        return 1;
    }

    return 0;
}

